function buildMindHeadMetaKey(cardId: string, key: string) {
  return `mind-head:${cardId}:${key}`
}

function testFacialCapability(key: string, label: string): CharacterFacialCapability {
  return {
    key,
    label,
    description: `${label} face cue`,
    source: 'preset',
    affectsMouth: false,
  }
}

function testActionCapability(key: string, label: string, source: CharacterActionCapability['source'] = 'builtin'): CharacterActionCapability {
  return {
    key,
    label,
    description: `${label} action cue`,
    source,
  }
}

